import { tags } from "typia";

/**
 * Overall search engagement and satisfaction metrics for the platform.
 *
 * Provides high-level performance indicators for the search functionality
 * including user satisfaction scores, search completion rates, and system
 * responsiveness metrics. This data helps evaluate the overall effectiveness of
 * the search system and drives platform improvements by identifying performance
 * bottlenecks and user experience issues.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ISearchEngagementMetrics = {
  /**
   * Total number of search queries executed in the analyzed period across all
   * users and categories. Primary metric for overall search platform usage.
   */
  total_searches: number & tags.Type<"int32">;

  /**
   * Number of unique users who performed searches during the analyzed period.
   * Indicates search feature adoption and user engagement levels.
   */
  unique_searchers: number & tags.Type<"int32">;

  /**
   * Average number of searches per active user, calculated as total_searches
   * divided by unique_searchers. Measures search engagement depth.
   */
  average_queries_per_user?: number | undefined;

  /**
   * Percentage of searches that returned relevant results, represented as
   * decimal value (0.0 to 1.0). Based on user click-through rates and result
   * interaction metrics.
   */
  search_success_rate: number & tags.Minimum<0> & tags.Maximum<1>;

  /**
   * Average search response time in milliseconds across all queries. Critical
   * performance metric for user experience optimization.
   */
  average_response_time_ms?: (number & tags.Type<"int32">) | undefined;

  /**
   * Aggregated user satisfaction rating for search functionality on scale
   * from 1.0 to 5.0. Based on post-search feedback surveys and implicit
   * engagement signals.
   */
  user_satisfaction_score?:
    | (number & tags.Minimum<1> & tags.Maximum<5>)
    | undefined;
};
